"""Small resilient client for the local order service.

Handles: token fetch/refresh on 401, rate limiting (waits exactly as long as the
service asks), transient 5xx / network errors / unparsable bodies (retry with
backoff). Every non-200 response is appended to an events log so the service's
real behaviour is visible afterwards. Anything unrecognised stops the run
rather than being guessed at.
"""
import json
import sys
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
HIDDEN_HEADERS = {"server", "content-type", "content-length", "connection"}


class Unexpected(Exception):
    pass


class Client:
    def __init__(self, events_path):
        self.token = None
        self.events = open(events_path, "a", buffering=1)
        self.tokens_issued = 0
        self.ok_since_token = 0
        self.waited_total = 0.0

    # -- logging ---------------------------------------------------------
    def ev(self, msg):
        line = f"{time.strftime('%H:%M:%S')} {msg}"
        self.events.write(line + "\n")
        print(line, file=sys.stderr, flush=True)

    # -- low level -------------------------------------------------------
    def _raw(self, method, path, auth=True):
        headers = {}
        if auth:
            headers["Authorization"] = "Bearer " + self.token
        req = urllib.request.Request(
            BASE + path,
            method=method,
            headers=headers,
            data=b"" if method == "POST" else None,
        )
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return r.status, dict(r.headers), r.read()
        except urllib.error.HTTPError as e:
            return e.code, dict(e.headers), e.read()

    def _brief(self, headers):
        return {k: v for k, v in headers.items() if k.lower() not in HIDDEN_HEADERS and k.lower() not in ("date",)}

    @staticmethod
    def _wait_from(headers, body):
        """Seconds the service asked us to wait, or None if it did not say."""
        for k, v in headers.items():
            if k.lower() == "retry-after":
                try:
                    return float(v)
                except ValueError:
                    return None
        try:
            parsed = json.loads(body)
        except ValueError:
            return None
        if isinstance(parsed, dict):
            for key in ("retry_after", "retry_after_seconds", "retry_after_s", "wait", "wait_seconds"):
                if key in parsed:
                    try:
                        return float(parsed[key])
                    except (TypeError, ValueError):
                        return None
        return None

    # -- token -----------------------------------------------------------
    def fetch_token(self, reason):
        for attempt in range(1, 11):
            try:
                status, headers, body = self._raw("POST", "/token", auth=False)
            except (urllib.error.URLError, OSError) as e:
                self.ev(f"NETERR POST /token attempt={attempt} {e!r}")
                time.sleep(min(2 ** attempt, 30))
                continue
            if status == 200:
                try:
                    tok = json.loads(body)["token"]
                except (ValueError, KeyError, TypeError):
                    self.ev(f"BADTOKENBODY {body[:200]!r}")
                    time.sleep(1)
                    continue
                self.token = tok
                self.tokens_issued += 1
                self.ok_since_token = 0
                self.ev(f"TOKEN issued={tok} reason={reason} total_issued={self.tokens_issued}")
                return
            wait = self._wait_from(headers, body) if status == 429 else None
            self.ev(f"HTTP {status} POST /token attempt={attempt} headers={self._brief(headers)} body={body[:300]!r}")
            if status == 429 and wait is not None:
                self._sleep(wait)
                continue
            if status >= 500:
                time.sleep(min(2 ** attempt, 30))
                continue
            raise Unexpected(f"token endpoint returned {status}: {body[:200]!r}")
        raise Unexpected("could not obtain a token after 10 attempts")

    def _sleep(self, seconds):
        # exactly what the service asked for, plus a small safety margin
        seconds = seconds + 0.25
        self.ev(f"WAIT {seconds:.2f}s (service-requested)")
        time.sleep(seconds)
        self.waited_total += seconds

    # -- GET with retries ------------------------------------------------
    def get(self, path, max_attempts=60, allow_404=False):
        """Return (status, parsed_json). status is 200, or 404 when allow_404."""
        backoff = 1.0
        consecutive_401 = 0
        for attempt in range(1, max_attempts + 1):
            if self.token is None:
                self.fetch_token("initial")
            try:
                status, headers, body = self._raw("GET", path)
            except (urllib.error.URLError, OSError) as e:
                self.ev(f"NETERR GET {path} attempt={attempt} {e!r}")
                time.sleep(backoff)
                backoff = min(backoff * 2, 30)
                continue

            if status == 200:
                try:
                    data = json.loads(body)
                except ValueError:
                    self.ev(f"BADJSON GET {path} attempt={attempt} body={body[:200]!r}")
                    time.sleep(backoff)
                    backoff = min(backoff * 2, 30)
                    continue
                self.ok_since_token += 1
                return 200, data

            text = body[:300].decode("utf-8", "replace")
            self.ev(f"HTTP {status} GET {path} attempt={attempt} ok_since_token={self.ok_since_token} headers={self._brief(headers)} body={text!r}")

            if status == 401:
                consecutive_401 += 1
                if consecutive_401 > 4:
                    raise Unexpected(f"repeated 401 on {path}: {text!r}")
                self.fetch_token(f"401 on {path}")
                continue
            if status == 429:
                wait = self._wait_from(headers, body)
                if wait is None:
                    raise Unexpected(f"429 without a readable wait time on {path}: headers={headers} body={text!r}")
                self._sleep(wait)
                continue
            if status == 404 and allow_404:
                return 404, None
            if status >= 500:
                time.sleep(backoff)
                backoff = min(backoff * 2, 30)
                continue
            raise Unexpected(f"unhandled HTTP {status} on {path}: headers={headers} body={text!r}")
        raise Unexpected(f"gave up on {path} after {max_attempts} attempts")

