    y, mo, d, h, mi, s = (int(x) for x in m.groups()[:6])
    tz = m.group(7)
    local_epoch = calendar.timegm((y, mo, d, h, mi, s))  # treats the wall-clock fields as if UTC
    if tz == "Z":
        off = 0
    else:
        sign = 1 if tz[0] == "+" else -1
        off = sign * (int(tz[1:3]) * 3600 + int(tz[4:6]) * 60)
    return local_epoch - off  # UTC = local - offset


def load_orders(data_dir):
    """Return (distinct_orders_in_first_seen_order, listings_total, duplicates_skipped)."""
    files = sorted(glob.glob(os.path.join(data_dir, "pages", "page_*.json")))
    seen = {}
    listings = 0
    for fp in files:
        with open(fp) as f:
            d = json.load(f)
        for it in d["items"]:
            listings += 1
            if it["id"] not in seen:
                seen[it["id"]] = it
    return list(seen.values()), listings, listings - len(seen)


def in_range(ts):
    return START_UTC <= to_utc(ts) < END_UTC_EXCL


def qualifies(order):
    return order["status"] == "shipped" and in_range(order["placed_at"])


def discounted_cents(amount_cents, discount_pct):
    """amount * (100 - pct) / 100, rounded half up to a whole cent, in pure integer arithmetic."""
    assert type(amount_cents) is int and type(discount_pct) is int and 0 <= discount_pct <= 100
    return (amount_cents * (100 - discount_pct) + 50) // 100

